const {useState,useEffect,useMemo}=React;
function normalizeStyle(style){if(typeof style!=='string')return style;return Object.fromEntries(style.split(';').filter(rule=>rule.includes(':')).map(rule=>{const i=rule.indexOf(':');const key=rule.slice(0,i).trim();const value=rule.slice(i+1).trim();return [key.startsWith('--')?key:key.replace(/-([a-z])/g,(_,c)=>c.toUpperCase()),value]}));}
const h=(t,p,...c)=>{if(p&&typeof p.style==='string')p={...p,style:normalizeStyle(p.style)};return React.createElement(t,p,...c)};
const html=htm.bind(h);
const API=window.SENTIMENTIQ_API_URL??'http://127.0.0.1:8000';
const apiFetch=(path,options={})=>{const token=sessionStorage.getItem('siq_token');const workspace=sessionStorage.getItem('siq_workspace');return fetch(API+path,{...options,headers:{...(options.headers||{}),...(token?{Authorization:'Bearer '+token}:{}),...(workspace?{'X-Workspace-ID':workspace}:{})}})};
const COLORS={Positive:'var(--pos)',Neutral:'var(--neu)',Negative:'var(--neg)'};
const SENTIMENTS=['Positive','Neutral','Negative'];
const NAV=[['overview','Overview','⌂'],['upload','Upload feedback','↑'],['explorer','Review explorer','☷'],['sentiment','Sentiment analysis','◉'],['topics','Topic intelligence','◇'],['trends','Trends & insights','↗'],['competitive','Competitor benchmark','⇄'],['reports','Reports','▤'],['settings','System status','⚙']];
const fmt=n=>Number(n||0).toLocaleString('en-IN');
const pct=n=>`${Number(n||0).toFixed(1)}%`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function Button({children,onClick,primary=false,disabled=false}){return html`<button class=${'btn'+(primary?' p':'')} disabled=${disabled} onClick=${onClick}>${children}</button>`}
function Header({title,subtitle,children}){return html`<div class="top"><div><h2>${title}</h2><p class="mut">${subtitle}</p></div><div class="row">${children}</div></div>`}
function Empty({title='No analysis yet',text='Upload a CSV of customer reviews to populate this workspace.' ,onClick}){return html`<div class="card" style="text-align:center;padding:48px 24px"><div style="font-size:36px;margin-bottom:10px">◌</div><h3>${title}</h3><p class="mut" style="margin:8px auto 18px;max-width:480px">${text}</p>${onClick&&html`<button class="btn p" onClick=${onClick}>Upload customer feedback</button>`}</div>`}
function Bars({values}){return html`<div class="bar">${SENTIMENTS.map(s=>html`<i key=${s} title=${s+' '+pct(values[s]?.percentage)} style=${{width:(values[s]?.percentage||0)+'%',background:COLORS[s]}}/>`)}</div>`}
function Donut({distribution,total}){const vals=SENTIMENTS.map(s=>distribution?.[s]?.percentage||0);let start=0;const colors=SENTIMENTS.map(s=>COLORS[s]);const stops=vals.map((v,i)=>{const a=start;start+=v;return `${colors[i]} ${a}% ${start}%`});return html`<div style=${{width:190,height:190,borderRadius:'50%',background:`conic-gradient(${stops.join(',')})`,display:'grid',placeItems:'center',margin:'12px auto'}}><div style=${{width:118,height:118,borderRadius:'50%',background:'var(--card)',display:'grid',placeItems:'center',textAlign:'center'}}><div><div class="big">${fmt(total)}</div><div class="sm mut">reviews</div></div></div></div>`}
function Metric({label,value,sub,color}){return html`<div class="card"><div class="sm mut">${label}</div><div class="big" style=${{margin:'7px 0',color:color||'var(--ink)'}}>${value}</div><div class="sm mut">${sub||'Based on selected dataset'}</div></div>`}
function Landing({go}){return html`<div class="land landing-page">
<nav class="landing-nav"><a class="brand-lockup" href="#" onClick=${e=>e.preventDefault()}><span class="brand-mark">S</span><span>Sentiment<span class="brand-iq">IQ</span><small>VOICE OF CUSTOMER INTELLIGENCE</small></span></a><div class="landing-links"><a href="#platform">Platform</a><a href="#workflow">How it works</a><a href="#insights">Insights</a></div><div class="row"><button class="btn" onClick=${()=>go('login')}>Sign in</button><button class="btn p" onClick=${()=>go('register')}>Get started <span aria-hidden="true">↗</span></button></div></nav>
<section class="hero landing-hero"><div class="hero-copy"><p class="eyebrow"><span class="live-dot"></span> CUSTOMER INTELLIGENCE, REIMAGINED</p><h1>Every review has a story.<br/><em>Find the signal.</em></h1><p class="hero-lede">Turn scattered customer feedback into a clear picture of what people love, what frustrates them, and what your team should do next.</p><div class="row hero-actions"><button class="btn p lg" onClick=${()=>go('register')}>Explore your workspace <span>↗</span></button><button class="btn lg btn-quiet" onClick=${()=>go('login')}>I already have an account</button></div><div class="hero-proof"><span class="proof-avatars"><i>✦</i><i>◉</i><i>↗</i></span><span>Built for teams that listen, learn and improve.</span></div></div>
<div class="hero-visual"><div class="visual-glow"></div><div class="dashboard-preview"><div class="preview-top"><div class="preview-brand"><span class="brand-mark mini">S</span><b>SentimentIQ</b></div><span class="preview-status"><i></i> ILLUSTRATIVE PREVIEW</span></div><div class="preview-heading"><div><small>OVERVIEW / CUSTOMER VOICE</small><h3>Your feedback at a glance</h3></div><span class="preview-date">Last 30 days⌄</span></div><div class="preview-kpis"><div><small>TOTAL REVIEWS</small><b>—</b><span>Across all channels</span></div><div><small>POSITIVE SIGNAL</small><b class="kpi-green">—</b><span>Customer sentiment</span></div><div><small>NEEDS ATTENTION</small><b class="kpi-amber">—</b><span>Negative feedback</span></div></div><div class="preview-chart"><div class="chart-title"><b>Sentiment over time</b><span>Positive · Neutral · Negative</span></div><div class="chart-area"><div class="chart-y"><i>100</i><i>75</i><i>50</i><i>25</i></div><svg viewBox="0 0 520 150" role="img" aria-label="Illustrative sentiment trend chart"><defs><linearGradient id="areaFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#8b7cff" stop-opacity=".28"/><stop offset="1" stop-color="#8b7cff" stop-opacity="0"/></linearGradient></defs><path d="M0 92 C40 86 45 55 90 62 S145 94 185 67 S240 35 280 48 S335 78 375 43 S440 34 520 16 L520 150 L0 150Z" fill="url(#areaFill)"/><path d="M0 92 C40 86 45 55 90 62 S145 94 185 67 S240 35 280 48 S335 78 375 43 S440 34 520 16" fill="none" stroke="#9b8cff" stroke-width="3" stroke-linecap="round"/><path d="M0 115 C45 112 60 102 90 105 S145 112 185 101 S245 92 280 98 S340 103 375 91 S445 95 520 83" fill="none" stroke="#63c9a5" stroke-width="2.5" stroke-linecap="round"/><path d="M0 132 C40 128 55 133 90 125 S145 130 185 123 S245 125 280 119 S340 129 375 119 S445 122 520 111" fill="none" stroke="#e7a65e" stroke-width="2" stroke-linecap="round"/></svg></div><div class="chart-months"><span>WEEK 01</span><span>WEEK 02</span><span>WEEK 03</span><span>WEEK 04</span></div></div><div class="preview-bottom"><div><span class="signal-icon">✦</span><span><b>Emerging signal</b><small>Delivery experience is trending upward</small></span></div><span class="signal-arrow">↗</span></div></div><div class="float-note note-one"><span class="note-icon">✦</span><span><b>Insight detected</b><small>3 themes need attention</small></span></div><div class="float-note note-two"><span class="note-dot"></span><span><b>Customer voice</b><small>One clear source of truth</small></span></div></div></section>
<section class="trust-strip"><span>ONE WORKSPACE FOR THE FULL CUSTOMER VOICE</span><div><b>LISTEN</b><i>✳</i><b>UNDERSTAND</b><i>✳</i><b>PRIORITISE</b><i>✳</i><b>IMPROVE</b></div></section>
<section class="feature-section" id="platform"><div class="section-intro"><p class="eyebrow">FROM FEEDBACK TO FORWARD MOTION</p><h2>Less guesswork.<br/><em>More understanding.</em></h2><p>Bring customer conversations together and make the patterns impossible to miss.</p></div><div class="feature-grid"><article class="feature-card feature-purple"><span class="feature-number">01 / SEE THE SENTIMENT</span><div class="feature-art sentiment-art"><div class="sentiment-ring"><span>78%<small>positive</small></span></div><div class="ring-label ring-a">Positive</div><div class="ring-label ring-b">Neutral</div><div class="ring-label ring-c">Negative</div></div><h3>Know how customers feel.</h3><p>Understand positive, neutral and negative feedback with clear sentiment breakdowns.</p></article><article class="feature-card feature-peach"><span class="feature-number">02 / FIND THE THEMES</span><div class="feature-art topic-art"><span>Delivery <b>↗</b></span><span>Product quality <b>↗</b></span><span>Support <b>↘</b></span><span>Pricing <b>↗</b></span></div><h3>Discover what drives it.</h3><p>Spot recurring topics, complaints, emerging phrases and signals worth investigating.</p></article><article class="feature-card feature-dark"><span class="feature-number">03 / TAKE ACTION</span><div class="feature-art action-art"><div><i>!</i><span><b>High priority feedback</b><small>Bring important issues forward</small></span></div><div><i>✓</i><span><b>Evidence-backed insights</b><small>Connect decisions to real reviews</small></span></div><div><i>↗</i><span><b>Shareable reports</b><small>Keep the whole team aligned</small></span></div></div><h3>Move from insight to action.</h3><p>Prioritise customer issues, compare datasets and share reports with your team.</p></article></div></section>
<section class="workflow-section" id="workflow"><div><p class="eyebrow">A SIMPLE, REPEATABLE WORKFLOW</p><h2>From raw reviews<br/>to <em>real direction.</em></h2><p>Start with the feedback you already have. SentimentIQ helps your team organise it, interpret it and decide what deserves attention.</p><button class="btn p lg" onClick=${()=>go('register')}>Create your workspace ↗</button></div><div class="workflow-steps">${[['01','Bring it together','Upload customer reviews from CSV or Excel.'],['02','Understand the patterns','Explore sentiment, topics, urgency and recurring signals.'],['03','Share what matters','Build reports and compare feedback across datasets.']].map(x=>html`<div class="workflow-step"><span>${x[0]}</span><div><h3>${x[1]}</h3><p>${x[2]}</p></div><b>↗</b></div>`)}</div></section>
<section class="closing-cta" id="insights"><p class="eyebrow">THE CUSTOMER VOICE, MADE CLEAR</p><h2>Make every piece of feedback<br/><em>count for something.</em></h2><p>Give your team a clearer way to listen, learn and improve.</p><button class="btn lg" onClick=${()=>go('register')}>Get started with SentimentIQ ↗</button></section>
<footer class="landing-footer"><span class="brand-lockup"><span class="brand-mark">S</span><span>Sentiment<span class="brand-iq">IQ</span><small>CUSTOMER FEEDBACK INTELLIGENCE</small></span></span><span>Built to turn customer signals into better decisions.</span><span>© SentimentIQ</span></footer>
</div>`}
function Overview({data,analyses,go,selectAnalysis,refresh}){const remove=async id=>{if(!window.confirm("Permanently delete this analysis and its linked report schedules and deliveries?"))return;try{const r=await apiFetch("/api/v1/analyses/"+id,{method:"DELETE"});if(!r.ok){const d=await r.json().catch(()=>({}));throw new Error(d.detail||"Delete failed")}const next=analyses.find(a=>a.id!==id);await refresh(next?.id||null)}catch(e){window.alert(e.message)}};if(!data)return html`<${Empty} onClick=${()=>go('upload')}/>`;const d=data.sentiment_distribution||{};const topics=data.topics||[];const complaints=data.complaints||[];return html`<div><${Header} title="Feedback overview" subtitle=${data.dataset_name+' · '+fmt(data.total_reviews)+' reviews analysed'}><button class="btn p" onClick=${()=>go('upload')}>＋ Upload feedback</button></${Header}><div class="g g4"><${Metric} label="Reviews analysed" value=${fmt(data.total_reviews)} sub="In selected dataset"/><${Metric} label="Positive sentiment" value=${pct(d.Positive?.percentage)} sub=${fmt(d.Positive?.count)+' reviews'} color=${COLORS.Positive}/><${Metric} label="Neutral sentiment" value=${pct(d.Neutral?.percentage)} sub=${fmt(d.Neutral?.count)+' reviews'} color=${COLORS.Neutral}/><${Metric} label="Negative sentiment" value=${pct(d.Negative?.percentage)} sub=${fmt(d.Negative?.count)+' reviews'} color=${COLORS.Negative}/></div><div class="g g4" style="margin-top:12px"><${Metric} label="High / critical priority" value=${fmt((data.priority_distribution?.High||0)+(data.priority_distribution?.Critical||0))} sub="Review before action" color="var(--neg)"/><${Metric} label="Repeated entries" value=${fmt(data.duplicate_summary?.duplicate_review_count||0)} sub="Exact text matches"/><${Metric} label="Emotion signals" value=${fmt(Object.values(data.emotion_distribution||{}).reduce((a,b)=>a+b,0))} sub="Keyword cues detected"/><${Metric} label="Emerging phrases" value=${fmt((data.emerging_terms||[]).length)} sub="Repeated terms to inspect"/></div><div class="g g2" style="margin-top:16px"><div class="card"><h3>Sentiment distribution</h3><${Donut} distribution=${d} total=${data.total_reviews}/><${Bars} values=${d}/><div class="row sp sm mut" style="margin-top:12px">${SENTIMENTS.map(s=>html`<span key=${s}>${s}: ${pct(d[s]?.percentage)}</span>`)}</div></div><div class="card"><h3>Topics customers mention</h3><p class="sm mut" style="margin:4px 0 14px">Sorted by number of mentions</p>${topics.length?topics.slice(0,7).map(t=>html`<div key=${t.topic} style="margin:12px 0"><div class="row sp sm"><b>${t.topic}</b><span class="mut">${fmt(t.mentions)} mentions</span></div><div class="bar" style="margin-top:6px"><i style=${{width:(t.mentions/Math.max(...topics.map(x=>x.mentions),1)*100)+'%',background:'var(--pri)'}}/></div></div>`):html`<p class="mut sm">No topic mentions identified yet.</p>`}</div></div><h3 style="margin:24px 0 12px">Insights from this dataset</h3><div class="g g3">${(data.insights||[]).length?(data.insights||[]).map((i,k)=>html`<div class="card" key=${k}><span class=${'tag '+(i.type==='attention'?'Negative':'Positive')}>${i.type==='attention'?'Attention':'Strength'}</span><h3 style="margin:10px 0">${i.title}</h3><p class="sm mut">${i.evidence}</p></div>`):html`<div class="card"><p class="mut sm">No significant insights were generated for this dataset.</p></div>`}</div><h3 style="margin:24px 0 12px">Saved analysis runs</h3><div class="card wrap" style="padding:0"><table><thead><tr><th>Dataset</th><th>Reviews</th><th>Created</th><th>Actions</th></tr></thead><tbody>${analyses.map(a=>html`<tr key=${a.id}><td>${a.dataset_name}</td><td>${fmt(a.total_reviews)}</td><td>${new Date(a.created_at+'Z').toLocaleString()}</td><td><div class="row"><button class="btn" onClick=${()=>selectAnalysis(a.id)}>View</button><button class="btn" onClick=${()=>remove(a.id)}>Delete</button></div></td></tr>`)}</tbody></table></div></div>`}
function Upload({refresh,go}){const[file,setFile]=useState(null),[name,setName]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState(''),[result,setResult]=useState(null),[drag,setDrag]=useState(false);const choose=f=>{setError('');setResult(null);if(!f)return;if(!/\.(csv|xlsx)$/i.test(f.name)){setError('Please choose a CSV or Excel .xlsx file.');return}if(f.size>10*1024*1024){setError('The file exceeds the 10 MB upload limit.');return}setFile(f);setName(f.name.replace(/\.(csv|xlsx)$/i,''))};const submit=async()=>{if(!file||!name.trim())return;setBusy(true);setError('');try{const fd=new FormData();fd.append('file',file);fd.append('dataset_name',name.trim());const r=await apiFetch('/api/v1/analyses',{method:'POST',body:fd});const body=await r.json();if(!r.ok)throw new Error(body.detail||'Analysis failed');setResult(body);await refresh(body.id)}catch(e){setError(e.message+' Check that the API is running and configured.')}finally{setBusy(false)}};return html`<div><${Header} title="Upload customer feedback" subtitle="Upload a CSV or Excel workbook (.xlsx). SentimentIQ will analyse and save the results."/><div class="card" style="max-width:850px"><div class="drop" style=${drag?{borderColor:'var(--pri)'}:null} onDragOver=${e=>{e.preventDefault();setDrag(true)}} onDragLeave=${()=>setDrag(false)} onDrop=${e=>{e.preventDefault();setDrag(false);choose(e.dataTransfer.files[0])}}><input type="file" accept=".csv,.xlsx,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" onChange=${e=>choose(e.target.files[0])}/><h3>Drop your CSV or Excel file here</h3><p class="sm mut" style="margin-top:6px">Maximum 10 MB · CSV must be UTF-8 · Required review text column</p></div>${file&&html`<div style="margin-top:18px"><div class="row sp"><b>${file.name}</b><span class="sm mut">${(file.size/1024).toFixed(1)} KB</span></div><label class="sm mut" style="display:block;margin:14px 0 5px">Dataset name</label><input style="width:100%" value=${name} onInput=${e=>setName(e.target.value)} placeholder="e.g. October product reviews"/><div class="row" style="margin-top:16px"><button class="btn p" disabled=${busy||!name.trim()} onClick=${submit}>${busy?'Analysing…':'Analyse feedback'}</button><button class="btn" disabled=${busy} onClick=${()=>{setFile(null);setResult(null);setError('')}}>Choose another file</button></div></div>`}${error&&html`<p style="color:var(--neg);margin-top:14px" role="alert">${error}</p>`}${busy&&html`<p class="sm mut" style="margin-top:14px">Processing reviews, calculating sentiment and identifying topics. Please keep this page open.</p>`}${result&&html`<div class="card" style="margin-top:18px"><span class="tag Positive">Analysis saved</span><h3 style="margin:10px 0">${result.dataset_name}</h3><p class="mut sm">${fmt(result.total_reviews)} reviews analysed. Your dashboard has been updated.</p><button class="btn p" style="margin-top:14px" onClick=${()=>go('overview')}>View dashboard</button></div>`}</div><div class="card" style="max-width:850px;margin-top:14px"><h3>Expected file format</h3><p class="sm mut" style="margin:6px 0 12px">CSV and Excel (.xlsx) files are supported. Include one text column named review_text, review, text, comment or feedback. Optional columns include rating, date and category. Maximum 20,000 review rows.</p><button class="btn" onClick=${()=>{const csv='review_id,review_text,rating,date,category\nR001,"The product quality is excellent",5,2026-10-10,Electronics\nR002,"Delivery was extremely slow",2,2026-10-11,Electronics\nR003,"Customer support was disappointing",1,2026-10-12,Home\nR004,"Good value and fast delivery",5,2026-10-13,Home\nR005,"The packaging arrived damaged",2,2026-10-14,Beauty\n';const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='sentimentiq-sample-reviews.csv';a.click();URL.revokeObjectURL(a.href)}}>Download sample CSV</button></div></div>`}
function Explorer({data}){const[q,sq]=useState(''),[sent,ss]=useState('All'),[topic,st]=useState('All'),[page,sp]=useState(0),[selected,select]=useState(null);const reviews=data?.reviews||[];const topics=data?.topics||[];const filtered=useMemo(()=>reviews.filter(r=>(sent==='All'||r.sentiment===sent)&&(topic==='All'||(r.topics||[]).includes(topic))&&r.review_text.toLowerCase().includes(q.toLowerCase())),[reviews,sent,topic,q]);const rows=filtered.slice(page*12,page*12+12);useEffect(()=>sp(0),[q,sent,topic]);if(!data)return html`<${Empty}/>`;return html`<div><${Header} title="Review explorer" subtitle=${fmt(filtered.length)+' matching reviews out of '+fmt(reviews.length)+' in '+data.dataset_name}/><div class="row" style="margin-bottom:14px"><input placeholder="Search review text…" value=${q} onInput=${e=>sq(e.target.value)} style="flex:1;min-width:180px"/><select value=${sent} onChange=${e=>ss(e.target.value)}><option>All</option>${SENTIMENTS.map(s=>html`<option key=${s}>${s}</option>`)}</select><select value=${topic} onChange=${e=>st(e.target.value)}><option>All</option>${topics.map(t=>html`<option key=${t.topic}>${t.topic}</option>`)}</select></div><div class="card wrap" style="padding:0"><table><thead><tr><th>Review</th><th>Sentiment</th><th>Language</th><th>Topics</th><th>Priority</th><th>Rating</th><th>Date</th></tr></thead><tbody>${rows.map(r=>html`<tr key=${r.review_id} class="k" onClick=${()=>select(r)}><td style="min-width:260px">${r.review_text}</td><td><span class=${'tag '+r.sentiment}>${r.sentiment}</span></td><td>${(r.language||'en').toUpperCase()}</td><td>${(r.topics||[]).join(', ')}</td><td><span class=${'tag '+(r.urgency?.priority==='Critical'||r.urgency?.priority==='High'?'Negative':'Neutral')}>${r.urgency?.priority||'—'}</span></td><td>${r.rating??'—'}</td><td>${r.date||'—'}</td></tr>`)}</tbody></table>${!rows.length&&html`<p class="mut" style="padding:24px">No reviews match these filters.</p>`}</div><div class="row sp" style="margin-top:12px"><span class="sm mut">Page ${filtered.length?page+1:0} of ${Math.ceil(filtered.length/12)}</span><div class="row"><button class="btn" disabled=${page===0} onClick=${()=>sp(page-1)}>Previous</button><button class="btn" disabled=${(page+1)*12>=filtered.length} onClick=${()=>sp(page+1)}>Next</button></div></div>${selected&&html`<div class="scrim" onClick=${()=>select(null)}><div class="card" style="maxWidth:520px;width:100%" onClick=${e=>e.stopPropagation()}><div class="row sp"><h3>Review details</h3><button class="btn" onClick=${()=>select(null)}>Close</button></div><p style="margin:18px 0">“${selected.review_text}”</p><span class=${'tag '+selected.sentiment}>${selected.sentiment}</span><p class="sm mut" style="margin-top:10px">Topics: ${(selected.topics||[]).join(', ')||'Other'} · Rating: ${selected.rating??'Not supplied'} · Date: ${selected.date||'Not supplied'}</p><p class="sm mut">Whole-review compound score: ${selected.compound}</p><p class="sm" style="margin-top:8px"><b>Priority:</b> ${selected.urgency?.priority||'Not scored'} · Urgency score: ${selected.urgency?.score??'—'} / 5</p><p class="sm mut">Urgency signals: ${(selected.urgency?.signals||[]).join(', ')||'None detected'}</p><p class="sm mut">Customer emotion signals: ${(selected.emotions||[]).join(', ')} · Language: ${(selected.language||'en').toUpperCase()}</p>${selected.duplicate_group&&html`<p class="sm" style="margin-top:8px;color:var(--neg)">Possible duplicate group: ${selected.duplicate_group}</p>`}${(selected.aspect_sentiments||[]).map(a=>html`<div style="border-top:1px solid var(--line);padding:10px 0"><div class="row sp"><b>${a.topic}</b><span class=${'tag '+a.sentiment}>${a.sentiment}</span></div><p class="sm mut" style="margin-top:5px">Evidence: ${a.evidence}</p></div>`) }</div></div>`}</div>`}
function Sentiment({data}){if(!data)return html`<${Empty}/>`;const d=data.sentiment_distribution;return html`<div><${Header} title="Sentiment analysis" subtitle="Understand the distribution of positive, neutral and negative feedback."/><div class="g g3">${SENTIMENTS.map(s=>html`<${Metric} key=${s} label=${s+' reviews'} value=${fmt(d[s].count)} sub=${pct(d[s].percentage)+' of all reviews'} color=${COLORS[s]}/>` )}</div><div class="card" style="margin-top:16px"><h3>Sentiment breakdown</h3><${Donut} distribution=${d} total=${data.total_reviews}/><${Bars} values=${d}/><div class="g g3" style="margin-top:16px">${SENTIMENTS.map(s=>html`<div class="sm" key=${s}><b>${s}</b><p class="mut">${fmt(d[s].count)} reviews · ${pct(d[s].percentage)}</p></div>`)}</div></div><div class="card" style="margin-top:16px"><h3>Methodology</h3><p class="sm mut" style="margin-top:8px">${data.methodology?.sentiment||'Sentiment classification methodology unavailable.'}</p><p class="sm mut" style="margin-top:8px">${data.methodology?.limitations||''}</p></div><div class="card" style="margin-top:16px"><h3>Detected language distribution</h3><p class="sm mut" style="margin:6px 0 12px">Heuristic language identification; mixed-language and code-switched reviews may be assigned imperfectly.</p>${Object.entries(data.language_distribution||{}).sort((a,b)=>b[1]-a[1]).map(([lang,count])=>html`<div class="row sp" style="padding:8px 0;border-bottom:1px solid var(--line)"><b>${({en:'English',es:'Spanish',fr:'French',hi:'Hindi'}[lang]||lang.toUpperCase())}</b><span class="sm mut">${fmt(count)} reviews · ${pct(count/Math.max(data.total_reviews,1)*100)}</span></div>`)}</div></div>`}
function Topics({data}){if(!data)return html`<${Empty}/>`;const topics=data.topics||[];return html`<div><${Header} title="Topic intelligence" subtitle="Explore what customers discuss and the sentiment associated with each theme."/><div class="card wrap" style="padding:0"><table><thead><tr><th>Topic</th><th>Mentions</th><th>Positive</th><th>Neutral</th><th>Negative</th><th>Negative share</th></tr></thead><tbody>${topics.map(t=>html`<tr key=${t.topic}><td><b>${t.topic}</b></td><td>${fmt(t.mentions)}</td><td>${fmt(t.positive)}</td><td>${fmt(t.neutral)}</td><td>${fmt(t.negative)}</td><td><span class=${'tag '+(t.negative_percentage>=30?'Negative':'Neutral')}>${pct(t.negative_percentage)}</span></td></tr>`)}</tbody></table></div><h3 style="margin:22px 0 12px">Recurring complaints</h3>${(data.complaints||[]).length?(data.complaints||[]).map(t=>html`<div class="card" style="margin-bottom:12px" key=${t.topic}><div class="row sp"><h3>${t.topic}</h3><span class="tag Negative">${fmt(t.negative)} negative mentions</span></div><p class="sm mut" style="margin:6px 0">${pct(t.negative_percentage)} of mentions for this topic are negative.</p><p class="sm" style="margin:8px 0"><b>Suggested next step:</b> ${t.recommended_action||'Review the evidence and investigate the underlying issue.'}</p>${(t.complaint_examples||[]).map((x,i)=>html`<p class="sm" key=${i} style="padding:8px 0;border-top:1px solid var(--line)">“${x}”</p>`)}</div>`):html`<div class="card"><p class="sm mut">No negative topic mentions were detected in this dataset.</p></div>`}<div class="g g2" style="margin-top:16px"><div class="card"><h3>Emerging customer signals</h3><p class="sm mut" style="margin:6px 0 12px">Repeated words and phrases outside the fixed topic taxonomy. Treat these as leads to investigate, not confirmed topics.</p>${(data.emerging_terms||[]).length?(data.emerging_terms||[]).slice(0,10).map(t=>html`<div class="row sp" style="padding:8px 0;border-bottom:1px solid var(--line)"><b>${t.term}</b><span class="sm mut">${fmt(t.mentions)} mentions</span></div>`):html`<p class="sm mut">No repeated emerging terms found.</p>`}</div><div class="card"><h3>Similar review clusters</h3><p class="sm mut" style="margin:6px 0 12px">Groups reviews with similar wording. Inspect the examples; similarity is not proof of the same underlying issue.</p>${(data.similar_review_clusters?.clusters||[]).length?(data.similar_review_clusters.clusters||[]).slice(0,8).map(c=>html`<div style="padding:9px 0;border-bottom:1px solid var(--line)"><div class="row sp"><b>${c.common_terms?.join(', ')||c.id}</b><span class="sm mut">${fmt(c.count)} reviews</span></div><p class="sm mut" style="margin-top:4px">${c.sample}</p></div>`):html`<p class="sm mut">No similar review clusters found in this dataset.</p>`}<p class="sm mut" style="margin-top:8px">Method: ${data.similar_review_clusters?.method||'Unavailable'}</p></div><div class="card"><h3>Customer emotion signals</h3><p class="sm mut" style="margin:6px 0 12px">Indicative emotion keywords detected in the uploaded reviews.</p>${Object.entries(data.emotion_distribution||{}).length?Object.entries(data.emotion_distribution||{}).sort((a,b)=>b[1]-a[1]).map(([emotion,count])=>html`<div class="row sp" style="padding:8px 0;border-bottom:1px solid var(--line)"><b>${emotion}</b><span class="sm mut">${fmt(count)}</span></div>`):html`<p class="sm mut">No emotion signals detected.</p>`}</div></div><div class="card" style="margin-top:14px"><div class="row sp"><div><h3>Priority queue</h3><p class="sm mut" style="margin-top:5px">High and critical reviews flagged for human review.</p></div><div class="big">${fmt((data.priority_reviews||[]).length)}</div></div>${(data.priority_reviews||[]).slice(0,6).map(r=>html`<div style="padding:10px 0;border-top:1px solid var(--line)"><div class="row sp"><span class=${'tag '+(r.urgency?.priority==='Critical'?'Negative':'Neutral')}>${r.urgency?.priority} priority</span><span class="sm mut">${r.sentiment} · ${r.urgency?.score}/5</span></div><p class="sm" style="margin-top:6px">${r.review_text}</p></div>`)}${!(data.priority_reviews||[]).length&&html`<p class="sm mut" style="margin-top:10px">No high-priority reviews flagged.</p>`}</div><div class="card" style="margin-top:14px"><h3>Duplicate review check</h3><p class="sm mut" style="margin-top:6px">${fmt(data.duplicate_summary?.duplicate_review_count||0)} repeated entries across ${fmt(data.duplicate_summary?.clusters?.length||0)} exact-match groups. Check before removing: identical wording can be legitimate.</p>${(data.duplicate_summary?.clusters||[]).map(c=>html`<p class="sm" style="padding:8px 0;border-top:1px solid var(--line)"><b>${c.count} entries</b> · ${c.sample}</p>`)}</div><div class="card" style="margin-top:14px"><h3>Topic methodology</h3><p class="sm mut" style="margin-top:8px">${data.methodology?.topics||'Topic method unavailable.'}</p><p class="sm mut" style="margin-top:8px">${data.methodology?.multilingual||''}</p><p class="sm mut" style="margin-top:8px">${data.methodology?.similarity||''}</p></div></div>`}
function Trends({data}){if(!data)return html`<${Empty}/>`;const groups={};(data.reviews||[]).forEach(r=>{if(!r.date)return;const d=new Date(r.date);if(Number.isNaN(d.getTime()))return;const k=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');groups[k]??={total:0,Positive:0,Neutral:0,Negative:0};groups[k].total++;groups[k][r.sentiment]++});const months=Object.entries(groups).sort(([a],[b])=>a.localeCompare(b));return html`<div><${Header} title="Trends & insights" subtitle="Date-based patterns calculated from the timestamps present in your uploaded reviews."/><div class="card"><h3>Monthly sentiment</h3>${months.length?html`<div class="wrap"><table><thead><tr><th>Month</th><th>Reviews</th><th>Positive</th><th>Neutral</th><th>Negative</th></tr></thead><tbody>${months.map(([m,v])=>html`<tr key=${m}><td>${new Date(m+'-01T00:00:00').toLocaleDateString(undefined,{month:'long',year:'numeric'})}</td><td>${fmt(v.total)}</td>${SENTIMENTS.map(s=>html`<td key=${s}>${pct(v[s]/v.total*100)}</td>`)}</tr>`)}</tbody></table></div>`:html`<p class="sm mut" style="margin-top:8px">No usable review dates were supplied. Add a date or created_at column to your CSV to enable trends.</p>`}</div><div class="g g2" style="margin-top:16px"><div class="card"><h3>Most discussed topic</h3><p class="big" style="margin-top:12px">${data.topics?.[0]?.topic||'—'}</p><p class="sm mut">${data.topics?.[0]?fmt(data.topics[0].mentions)+' mentions':''}</p></div><div class="card"><h3>Highest negative share</h3><p class="big" style="margin-top:12px">${[...(data.topics||[])].sort((a,b)=>b.negative_percentage-a.negative_percentage)[0]?.topic||'—'}</p><p class="sm mut">Based on topic-level negative mentions.</p></div></div></div>`}
function Competitive({analyses}){const[selected,setSelected]=useState([]),[result,setResult]=useState(null),[busy,setBusy]=useState(false),[error,setError]=useState('');useEffect(()=>{setSelected(analyses.slice(0,2).map(a=>a.id));setResult(null)},[analyses]);const toggle=id=>{setSelected(prev=>prev.includes(id)?prev.filter(x=>x!==id):(prev.length<8?[...prev,id]:prev))};const compare=async()=>{setBusy(true);setError('');setResult(null);try{const r=await apiFetch('/api/v1/competitive/benchmark',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({analysis_ids:selected})});const d=await r.json();if(!r.ok)throw new Error(d.detail||'Benchmark failed');setResult(d)}catch(e){setError(e.message)}finally{setBusy(false)}};const download=()=>{if(!result)return;const rows=[['Dataset','Reviews','Positive %','Neutral %','Negative %','Net sentiment','High priority %'],...result.datasets.map(d=>[d.brand,d.review_count,d.sentiment.Positive.percentage,d.sentiment.Neutral.percentage,d.sentiment.Negative.percentage,d.net_sentiment,d.high_priority_percentage])];const csv=rows.map(row=>row.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));const a=document.createElement('a');a.href=url;a.download='sentimentiq-competitive-benchmark.csv';a.click();URL.revokeObjectURL(url)};return html`<div><${Header} title="Competitor benchmark" subtitle="Compare review datasets you've uploaded to this workspace. Name each dataset after the brand it represents."/><div class="card"><div class="row sp"><div><h3>Select datasets</h3><p class="sm mut" style="margin-top:5px">Choose 2–8 datasets. Each dataset name is used as its brand label.</p></div><span class="tag">${selected.length} selected</span></div>${analyses.length<2?html`<p class="sm mut" style="margin-top:14px">You need at least two saved datasets. Upload separate review files for your business and the competitors you want to compare.</p>`:html`<div class="g g2" style="margin-top:12px">${analyses.map(a=>html`<label key=${a.id} class="row" style="gap:10px;padding:12px;border:1px solid var(--line);border-radius:9px;align-items:flex-start"><input type="checkbox" checked=${selected.includes(a.id)} disabled=${!selected.includes(a.id)&&selected.length>=8} onChange=${()=>toggle(a.id)}/><span><b>${a.dataset_name}</b><span class="sm mut" style="display:block">${fmt(a.total_reviews)} reviews · ${new Date(a.created_at+'Z').toLocaleDateString()}</span></span></label>`)}</div><button class="btn p" style="margin-top:16px" disabled=${selected.length<2||busy} onClick=${compare}>${busy?'Comparing…':'Compare selected datasets'}</button>`}${error&&html`<p role="alert" style="color:var(--neg);margin-top:12px">${error}</p>`}</div>${result&&html`<div><div class="row sp" style="margin:18px 0 10px"><h3>Benchmark results</h3><button class="btn" onClick=${download}>Download comparison CSV</button></div><div class="g g3">${result.datasets.map(d=>html`<div class="card" key=${d.analysis_id}><p class="sm mut">${d.brand}</p><div class="big" style=${{color:d.net_sentiment>=0?'var(--pos)':'var(--neg)'}}>${d.net_sentiment>0?'+':''}${d.net_sentiment}</div><p class="sm mut">Net sentiment points</p><div class="bar" style="margin:14px 0 8px"><i style=${{width:d.sentiment.Positive.percentage+'%',background:COLORS.Positive}}/><i style=${{width:d.sentiment.Neutral.percentage+'%',background:COLORS.Neutral}}/><i style=${{width:d.sentiment.Negative.percentage+'%',background:COLORS.Negative}}/></div><div class="sm mut">${fmt(d.review_count)} reviews · ${pct(d.sentiment.Positive.percentage)} positive · ${pct(d.sentiment.Negative.percentage)} negative</div><p class="sm" style="margin-top:10px">High / critical priority: <b>${pct(d.high_priority_percentage)}</b></p></div>`)}</div><div class="card wrap" style="padding:0;margin-top:14px"><table><thead><tr><th>Topic</th><th>Brand</th><th>Mentions</th><th>Negative</th><th>Positive</th><th>Negative share</th></tr></thead><tbody>${result.topic_comparison.flatMap(t=>t.brands.map(b=>html`<tr key=${t.topic+'-'+b.brand}><td><b>${t.topic}</b></td><td>${b.brand}</td><td>${fmt(b.mentions)}</td><td>${fmt(b.negative)}</td><td>${fmt(b.positive)}</td><td><span class=${'tag '+(b.negative_percentage>=30?'Negative':'Neutral')}>${pct(b.negative_percentage)}</span></td></tr>`))}</tbody></table></div><h3 style="margin:20px 0 10px">Competitive signals</h3><div class="g g2">${result.insights.map((i,k)=>html`<div class="card" key=${k}><span class=${'tag '+(i.type==='attention'?'Negative':'Positive')}>${i.type==='attention'?'Opportunity to investigate':'Relative strength'}</span><h3 style="margin:10px 0">${i.title}</h3><p class="sm mut">${i.evidence}</p></div>`)}</div><p class="sm mut" style="margin-top:12px">${result.methodology}</p></div>`}</div>`}
function Reports({data}){const[schedules,setSchedules]=useState([]),[deliveries,setDeliveries]=useState([]),[email,setEmail]=useState(''),[cadence,setCadence]=useState('weekly'),[hour,setHour]=useState('9'),[weekday,setWeekday]=useState('1'),[monthday,setMonthday]=useState('1'),[threshold,setThreshold]=useState(''),[busy,setBusy]=useState(false),[message,setMessage]=useState(''),[error,setError]=useState('');const refresh=async()=>{try{const[a,b]=await Promise.all([apiFetch('/api/v1/report-schedules'),apiFetch('/api/v1/report-deliveries')]);if(a.ok)setSchedules(await a.json());if(b.ok)setDeliveries(await b.json())}catch(e){setError(e.message)}};useEffect(()=>{refresh()},[]);if(!data)return html`<${Empty}/>`;const download=async(path,name)=>{setError('');try{const r=await apiFetch(path);if(!r.ok){const d=await r.json().catch(()=>({}));throw new Error(d.detail||'Download failed')}const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}catch(e){setError(e.message)}};const localDownload=(name,content,type)=>{const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)};const create=async e=>{e.preventDefault();setBusy(true);setError('');setMessage('');try{const body={analysis_id:data.id,recipient_email:email,cadence,hour_utc:Number(hour),day_of_week:Number(weekday),day_of_month:Number(monthday),negative_alert_threshold:threshold===''?null:Number(threshold)};const r=await apiFetch('/api/v1/report-schedules',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();if(!r.ok)throw new Error(d.detail||'Could not create schedule');setMessage('Schedule created. Next run: '+new Date(d.next_run_at).toLocaleString()+' (UTC schedule time).');setEmail('');setThreshold('');await refresh()}catch(e){setError(e.message)}finally{setBusy(false)}};const remove=async id=>{try{const r=await apiFetch('/api/v1/report-schedules/'+id,{method:'DELETE'});if(!r.ok)throw new Error('Could not delete schedule');await refresh()}catch(e){setError(e.message)}};const runNow=async id=>{setError('');setMessage('Generating report…');try{const r=await apiFetch('/api/v1/report-schedules/'+id+'/run',{method:'POST'}),d=await r.json();if(!r.ok)throw new Error(d.detail||'Could not run report');setMessage(d.status==='sent'?'Report emailed successfully.':(d.error_message||'PDF generated and saved; email not sent.'));await refresh()}catch(e){setError(e.message)}};const csv=['review_id,review_text,sentiment,language,expected_sentiment,compound,priority,urgency_score,emotions,duplicate_group,rating,date,topics,aspect_sentiments',...(data.reviews||[]).map(r=>[r.review_id,`"${String(r.review_text).replace(/"/g,'""')}"`,r.sentiment,r.language||'en',r.expected_sentiment||'',r.compound,r.urgency?.priority||'',r.urgency?.score??'',`"${(r.emotions||[]).join('; ')}"`,r.duplicate_group||'',r.rating??'',r.date??'',`"${(r.topics||[]).join('; ')}"`,`"${(r.aspect_sentiments||[]).map(a=>a.topic+': '+a.sentiment).join('; ')}"`].join(','))].join('\n');const report={dataset_name:data.dataset_name,total_reviews:data.total_reviews,sentiment_distribution:data.sentiment_distribution,topics:data.topics,complaints:data.complaints,insights:data.insights,emotion_distribution:data.emotion_distribution,priority_distribution:data.priority_distribution,priority_reviews:data.priority_reviews,duplicate_summary:data.duplicate_summary,emerging_terms:data.emerging_terms,similar_review_clusters:data.similar_review_clusters,language_distribution:data.language_distribution,model_evaluation:data.model_evaluation,methodology:data.methodology};return html`<div><${Header} title="Reports & automation" subtitle="Export evidence-based reports and schedule recurring email summaries."/><div class="g g2"><div class="card"><h3>PDF executive report</h3><p class="sm mut" style="margin:8px 0 16px">Formatted PDF with sentiment distribution, key findings, topic signals, complaint guidance and limitations.</p><button class="btn p" onClick=${()=>download('/api/v1/reports/'+data.id+'.pdf','sentimentiq-report.pdf')}>Download PDF report</button></div><div class="card"><h3>Data exports</h3><p class="sm mut" style="margin:8px 0 16px">Download the review records or full analysis payload.</p><div class="row"><button class="btn" onClick=${()=>localDownload('sentimentiq-reviews.csv',csv,'text/csv')}>Reviews CSV</button><button class="btn" onClick=${()=>localDownload('sentimentiq-analysis.json',JSON.stringify(report,null,2),'application/json')}>Analysis JSON</button></div></div></div><div class="card" style="margin-top:16px"><h3>Schedule recurring reports</h3><p class="sm mut" style="margin:6px 0 14px">Schedules use UTC. Configure SMTP on the backend to email PDF attachments. Without SMTP, generated PDFs are saved in delivery history for download.</p><form onSubmit=${create}><div class="g g2"><label class="sm mut">Recipient email<input required type="email" style="width:100%;margin-top:5px" value=${email} onInput=${e=>setEmail(e.target.value)} placeholder="reports@yourcompany.com"/></label><label class="sm mut">Frequency<select style="width:100%;margin-top:5px" value=${cadence} onChange=${e=>setCadence(e.target.value)}><option value="weekly">Weekly</option><option value="monthly">Monthly</option></select></label><label class="sm mut">Hour (UTC)<select style="width:100%;margin-top:5px" value=${hour} onChange=${e=>setHour(e.target.value)}>${Array.from({length:24},(_,i)=>html`<option value=${i}>${String(i).padStart(2,'0')}:00</option>`)}</select></label>${cadence==='weekly'?html`<label class="sm mut">Day of week<select style="width:100%;margin-top:5px" value=${weekday} onChange=${e=>setWeekday(e.target.value)}>${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'].map((d,i)=>html`<option value=${i}>${d}</option>`)}</select></label>`:html`<label class="sm mut">Day of month<select style="width:100%;margin-top:5px" value=${monthday} onChange=${e=>setMonthday(e.target.value)}>${Array.from({length:28},(_,i)=>html`<option value=${i+1}>${i+1}</option>`)}</select></label>`}<label class="sm mut">Negative sentiment alert threshold (%)<input type="number" min="0" max="100" step="1" style="width:100%;margin-top:5px" value=${threshold} onInput=${e=>setThreshold(e.target.value)} placeholder="Optional, e.g. 35"/></label></div><button class="btn p" style="margin-top:14px" disabled=${busy||!data.id}>${busy?'Saving…':'Create report schedule'}</button></form>${message&&html`<p class="sm" style="color:var(--pos);margin-top:12px">${message}</p>`}${error&&html`<p class="sm" role="alert" style="color:var(--neg);margin-top:12px">${error}</p>`}</div><div class="card" style="margin-top:16px"><div class="row sp"><h3>Scheduled reports</h3><button class="btn" onClick=${refresh}>Refresh</button></div>${schedules.length?schedules.map(s=>html`<div class="row sp" style="padding:12px 0;border-bottom:1px solid var(--line);align-items:flex-start"><div><b>${s.cadence==='weekly'?'Weekly':'Monthly'} · ${s.recipient_email}</b><p class="sm mut">Next: ${new Date(s.next_run_at).toLocaleString()} · Last status: ${s.last_status||'Not run yet'}${s.negative_alert_threshold!==null?' · Alert at '+s.negative_alert_threshold+'% negative':''}</p></div><div class="row"><button class="btn" onClick=${()=>runNow(s.id)}>Run now</button><button class="btn" onClick=${()=>remove(s.id)}>Delete</button></div></div>`):html`<p class="sm mut" style="margin-top:12px">No report schedules yet.</p>`}</div><div class="card" style="margin-top:16px"><h3>Recent report deliveries</h3>${deliveries.length?deliveries.map(d=>html`<div class="row sp" style="padding:10px 0;border-bottom:1px solid var(--line)"><div><b>${d.subject}</b><p class="sm mut">${new Date(d.created_at).toLocaleString()} · ${d.recipient_email} · ${d.status}${d.error_message?' · '+d.error_message:''}</p></div><button class="btn" onClick=${()=>download('/api/v1/report-deliveries/'+d.id+'.pdf','sentimentiq-scheduled-report.pdf')}>Download PDF</button></div>`):html`<p class="sm mut" style="margin-top:10px">No report deliveries yet.</p>`}</div><div class="card" style="margin-top:16px"><h3>Report preview</h3><p class="sm mut" style="margin:6px 0 14px">${data.dataset_name} · ${fmt(data.total_reviews)} reviews · ${new Date().toLocaleDateString()}</p><div class="g g3">${SENTIMENTS.map(s=>html`<div><div class="big" style=${{color:COLORS[s]}}>${pct(data.sentiment_distribution[s].percentage)}</div><div class="sm mut">${s}</div></div>`)}</div><h3 style="margin-top:20px">Key findings</h3>${(data.insights||[]).map((i,k)=>html`<p class="sm" key=${k} style="padding:8px 0;border-bottom:1px solid var(--line)"><b>${i.title}</b><br/><span class="mut">${i.evidence}</span></p>`)}</div></div>`}
function Settings({health,analyses}){
 const[audit,setAudit]=useState([]),[days,setDays]=useState('180'),[busy,setBusy]=useState(false),[message,setMessage]=useState(''),[error,setError]=useState('');
 const loadAudit=async()=>{try{const r=await apiFetch('/api/v1/audit-events');const d=await r.json();if(!r.ok)throw new Error(d.detail||'Audit history unavailable');setAudit(d)}catch(e){setError(e.message)}};
 useEffect(()=>{loadAudit()},[]);
 const purge=async()=>{if(!window.confirm('Permanently delete analyses older than '+days+' days, including linked schedules and retained report PDFs? This cannot be undone.'))return;setBusy(true);setError('');setMessage('');try{const r=await apiFetch('/api/v1/data-retention/purge',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({older_than_days:Number(days),confirm:true})});const d=await r.json();if(!r.ok)throw new Error(d.detail||'Retention purge failed');setMessage(d.deleted_analyses+' old analyses permanently deleted.');await loadAudit()}catch(e){setError(e.message)}finally{setBusy(false)}};
 return html`<div><${Header} title="System & data controls" subtitle="Connection, analysis methods, audit history and workspace data retention."/><div class="g g2"><div class="card"><h3>API connection</h3><p style="margin:10px 0"><span class=${'tag '+(health?'Positive':'Negative')}>${health?'Connected':'Unavailable'}</span></p><p class="sm mut">${API}</p></div><div class="card"><h3>Saved analyses</h3><div class="big" style="margin-top:10px">${analyses.length}</div><p class="sm mut">Analysis runs stored by the backend.</p></div><div class="card"><h3>Sentiment method</h3><p class="sm mut" style="margin-top:8px">VADER lexicon/rule-based scoring when installed; an offline fallback may be used. Scores are not calibrated probabilities.</p></div><div class="card"><h3>Topic method</h3><p class="sm mut" style="margin-top:8px">An explainable keyword taxonomy. A review may be assigned to multiple topics. It is not an unsupervised topic model.</p></div><div class="card"><h3>Priority & emotion signals</h3><p class="sm mut" style="margin-top:8px">Keyword-based triage and emotion cues. These are heuristics for human review, not calibrated risk scores or psychological diagnoses.</p></div><div class="card"><h3>Duplicate & emerging signal checks</h3><p class="sm mut" style="margin-top:8px">Exact normalized text matching and repeated term extraction. Paraphrases are not deduplicated and emerging terms require human validation.</p></div><div class="card"><h3>Multilingual & similarity analysis</h3><p class="sm mut" style="margin-top:8px">Heuristic language detection for English, Spanish, French and Hindi. Similar-review grouping uses TF-IDF by default; optional local sentence-transformer embeddings can be configured. Not a translation engine.</p></div><div class="card"><h3>Security controls</h3><p class="sm mut" style="margin-top:8px">API security headers, per-process request throttling, workspace-scoped access and permanent-deletion audit events. A shared edge rate limiter is still recommended for multi-replica public deployments.</p></div></div><div class="card" style="margin-top:16px"><h3>Workspace data retention</h3><p class="sm mut" style="margin:8px 0 14px">Permanently delete analyses older than a selected number of days. Linked report schedules and retained PDF deliveries are also deleted. Minimum retention window: 30 days. Workspace owner permission required.</p><div class="row"><input type="number" min="30" max="3650" value=${days} onInput=${e=>setDays(e.target.value)} style="max-width:150px"/><button class="btn" disabled=${busy||Number(days)<30||Number(days)>3650} onClick=${purge}>${busy?'Processing…':'Purge old data'}</button></div>${message&&html`<p class="sm" style="color:var(--pos);margin-top:10px">${message}</p>`}${error&&html`<p class="sm" style="color:var(--neg);margin-top:10px">${error}</p>`}</div><div class="card" style="margin-top:16px"><div class="row sp"><div><h3>Workspace audit history</h3><p class="sm mut">Latest 100 deletion and retention events. Workspace owner permission required.</p></div><button class="btn" onClick=${loadAudit}>Refresh</button></div>${audit.length?html`<div class="wrap" style="margin-top:12px"><table><thead><tr><th>Action</th><th>Resource</th><th>Details</th><th>Date</th></tr></thead><tbody>${audit.map(x=>html`<tr key=${x.id}><td>${x.action}</td><td>${x.resource_type}</td><td>${x.details?.dataset_name||x.details?.deleted_count||x.resource_id}</td><td>${new Date(x.created_at).toLocaleString()}</td></tr>`)}</tbody></table></div>`:html`<p class="sm mut" style="margin-top:12px">No audit events available, or this account does not have workspace-owner permission.</p>`}</div></div>`
}
function AuthScreen({onAuth,initialMode='login'}){const[mode,setMode]=useState(initialMode),[name,setName]=useState(''),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[workspace,setWorkspace]=useState('My business'),[busy,setBusy]=useState(false),[error,setError]=useState('');const submit=async e=>{e.preventDefault();setBusy(true);setError('');try{const body=mode==='register'?{full_name:name,email,password,workspace_name:workspace}:{email,password};const r=await fetch(API+'/api/v1/auth/'+mode,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw new Error(d.detail||'Authentication failed');sessionStorage.setItem('siq_token',d.access_token);sessionStorage.setItem('siq_workspace',d.active_workspace_id||d.workspaces?.[0]?.id||'');onAuth(d)}catch(err){setError(err.message)}finally{setBusy(false)}};return html`<div class="land"><nav class="row sp" style="padding:20px 0;border-bottom:1px solid var(--line)"><b style="font:600 24px Fraunces">SentimentIQ</b><span class="sm mut">Customer feedback intelligence</span></nav><section style="max-width:470px;margin:8vh auto 0"><p class="eye">YOUR CUSTOMER SIGNAL, IN FOCUS</p><h1 style="font-size:42px;margin:12px 0">${mode==='login'?'Welcome back.':'Create your workspace.'}</h1><p class="mut" style="margin-bottom:24px">${mode==='login'?'Sign in to access your feedback insights.':'Start analysing customer feedback with your team.'}</p><form class="card" onSubmit=${submit}><h3>${mode==='login'?'Sign in':'Create account'}</h3>${mode==='register'&&html`<label class="sm mut" style="display:block;margin:14px 0 5px">Full name</label><input required minLength="2" style="width:100%" value=${name} onInput=${e=>setName(e.target.value)} placeholder="Your name"/><label class="sm mut" style="display:block;margin:14px 0 5px">Business / workspace name</label><input required minLength="2" style="width:100%" value=${workspace} onInput=${e=>setWorkspace(e.target.value)} placeholder="Your business"/>`}<label class="sm mut" style="display:block;margin:14px 0 5px">Email</label><input required type="email" autocomplete="email" style="width:100%" value=${email} onInput=${e=>setEmail(e.target.value)} placeholder="you@company.com"/><label class="sm mut" style="display:block;margin:14px 0 5px">Password</label><input required type="password" minLength=${mode==='register'?10:1} autocomplete=${mode==='login'?'current-password':'new-password'} style="width:100%" value=${password} onInput=${e=>setPassword(e.target.value)} placeholder=${mode==='register'?'At least 10 characters':'Your password'}/>${error&&html`<p role="alert" style="color:var(--neg);margin-top:12px">${error}</p>`}<button class="btn p" style="width:100%;margin-top:20px" disabled=${busy}>${busy?'Please wait…':mode==='login'?'Sign in':'Create account'}</button><p class="sm mut" style="text-align:center;margin-top:16px">${mode==='login'?"New to SentimentIQ?":"Already have an account?"} <a href="#" onClick=${e=>{e.preventDefault();setMode(mode==='login'?'register':'login');setError('')}}>${mode==='login'?'Create an account':'Sign in'}</a></p></form><p class="sm mut" style="text-align:center;margin-top:18px">Use a unique password. This development build stores the session token in this browser tab.</p></section></div>`}
function App(){const[authenticated,setAuthenticated]=useState(!!sessionStorage.getItem('siq_token')),[workspaceId,setWorkspaceId]=useState(sessionStorage.getItem('siq_workspace')||''),[workspaceList,setWorkspaceList]=useState([]),[page,setPage]=useState(sessionStorage.getItem('siq_token')?'overview':'home'),[analyses,setAnalyses]=useState([]),[active,setActive]=useState(null),[data,setData]=useState(null),[health,setHealth]=useState(false),[error,setError]=useState(''),[nav,setNav]=useState(false);const load=async preferred=>{try{const [hres,ares]=await Promise.all([fetch(API+'/health'),apiFetch('/api/v1/analyses')]);setHealth(hres.ok);if(!ares.ok)throw new Error('Unable to load saved analyses');const list=await ares.json();setAnalyses(list);const id=preferred||active||list[0]?.id;if(id){const dres=await apiFetch('/api/v1/analyses/'+id);if(!dres.ok)throw new Error('Unable to load selected analysis');const detail=await dres.json();setData(detail);setActive(id)}else{setData(null);setActive(null)}setError('')}catch(e){setHealth(false);setError(e.message||'API connection failed')}};useEffect(()=>{if(authenticated){apiFetch('/api/v1/workspaces').then(r=>r.ok?r.json():[]).then(setWorkspaceList);load()}},[authenticated,workspaceId]);const onAuth=d=>{setWorkspaceList(d.workspaces||[]);setWorkspaceId(d.active_workspace_id||'');setAuthenticated(true);setPage('overview')};const go=p=>{setPage(p);setNav(false);window.scrollTo(0,0)};if(!authenticated)return page==='login'||page==='register'?html`<${AuthScreen} onAuth=${onAuth} initialMode=${page}/>`:html`<${Landing} go=${go}/>`;const logout=()=>{sessionStorage.removeItem('siq_token');sessionStorage.removeItem('siq_workspace');setAuthenticated(false);setAnalyses([]);setData(null)};const createWorkspace=async()=>{const name=window.prompt('Enter a name for the new workspace');if(!name||!name.trim())return;try{const r=await apiFetch('/api/v1/workspaces',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:name.trim()})});const w=await r.json();if(!r.ok)throw new Error(w.detail||'Could not create workspace');setWorkspaceList(prev=>[...prev,w]);sessionStorage.setItem('siq_workspace',w.id);setWorkspaceId(w.id);setActive(null);setData(null)}catch(e){setError(e.message)}};const selectAnalysis=id=>load(id);const component=page==='overview'?html`<${Overview} data=${data} analyses=${analyses} go=${go} selectAnalysis=${selectAnalysis} refresh=${load}/>`:page==='upload'?html`<${Upload} refresh=${load} go=${go}/>`:page==='explorer'?html`<${Explorer} data=${data}/>`:page==='sentiment'?html`<${Sentiment} data=${data}/>`:page==='topics'?html`<${Topics} data=${data}/>`:page==='trends'?html`<${Trends} data=${data}/>`:page==='competitive'?html`<${Competitive} analyses=${analyses}/>`:page==='reports'?html`<${Reports} key=${workspaceId} data=${data}/>`:html`<${Settings} health=${health} analyses=${analyses}/>`;if(page==='home')return html`<${Landing} go=${go}/>`;return html`<div class="app"><aside class=${'side'+(nav?' open':'')}><div class="row sp" style="padding:4px 8px 14px"><b style="font:600 20px Fraunces">SentimentIQ</b></div><div style="padding:8px 12px;border:1px solid var(--line);border-radius:8px;margin-bottom:10px"><div class="sm mut">Workspace</div><select style="width:100%;margin-top:5px" value=${workspaceId} onChange=${e=>{sessionStorage.setItem('siq_workspace',e.target.value);setWorkspaceId(e.target.value);setActive(null);setData(null)}}>${workspaceList.map(w=>html`<option value=${w.id}>${w.name}</option>`)}</select><button class="btn" style="width:100%;margin-top:7px" onClick=${createWorkspace}>+ New workspace</button></div>${NAV.map(n=>html`<button key=${n[0]} class=${'nav'+(page===n[0]?' on':'')} onClick=${()=>go(n[0])}><span style="width:20px">${n[2]}</span>${n[1]}</button>`)}<div style="flex:1"/><div class="sm mut" style="padding:12px;border-top:1px solid var(--line)">SentimentIQ · Workspace secured</div><button class="nav" onClick=${logout}>↪ Sign out</button></aside><main class="main"><div class="row sp"><button class="btn burger" onClick=${()=>setNav(!nav)}>☰ Menu</button><div class="sm mut">API <span class=${'tag '+(health?'Positive':'Negative')}>${health?'Online':'Offline'}</span></div></div>${error&&html`<div class="card" style="margin:12px 0;border-color:var(--neg)"><p class="sm" style="color:var(--neg)">${error}. Check that the backend is running at ${API}.</p><button class="btn" style="margin-top:8px" onClick=${()=>load()}>Retry connection</button></div>`}${active&&analyses.length>1&&html`<div class="row" style="margin:12px 0"><label class="sm mut">Selected dataset</label><select value=${active} onChange=${e=>selectAnalysis(e.target.value)}>${analyses.map(a=>html`<option key=${a.id} value=${a.id}>${a.dataset_name} (${fmt(a.total_reviews)} reviews)</option>`)}</select></div>`}<div style="margin-top:16px">${component}</div><p class="sm mut" style="margin-top:36px">SentimentIQ analyses the data you upload. Results depend on review quality, language and the selected baseline methods.</p></main></div>`}
ReactDOM.createRoot(document.getElementById('root')).render(html`<${App}/>`);
